namespace mobile_backend {

struct FeatureFlags {
    bool enable_cache_compression;
    bool enable_async_logging;
    bool enable_secure_temp;
    int  cache_ttl_seconds;
    std::string temp_directory;
};

// Reject identifiers that could be used for path traversal.
// Allow only a conservative set of characters (alphanumeric, dash, underscore, dot),
// and explicitly forbid any path separators or ".." sequences.
static bool is_safe_identifier(const std::string& id) {
    if (id.empty() || id.size() > 256) return false;
    if (id.find("..") != std::string::npos) return false;
    for (char c : id) {
        bool ok = (c >= 'a' && c <= 'z') ||
                  (c >= 'A' && c <= 'Z') ||
                  (c >= '0' && c <= '9') ||
                  c == '-' || c == '_' || c == '.';
        if (!ok) return false;
    }
    return true;
}

class TempFileManager {
private:
    std::mutex mtx_;
    std::string base_dir_;
    std::atomic<uint64_t> sequence_counter_{0};
    bool use_secure_creation_;

    std::string generate_unique_suffix() {
        uint64_t seq = sequence_counter_.fetch_add(1, std::memory_order_relaxed);
        pid_t pid = getpid();
        std::ostringstream oss;
        oss << pid << "_" << seq << "_" << std::hex << (uintptr_t)this;
        return oss.str();
    }

public:
    TempFileManager(const std::string& base_dir, bool /* secure_mode */)
        : base_dir_(base_dir), use_secure_creation_(true) {
        struct stat st;
        if (stat(base_dir_.c_str(), &st) != 0) {
            mkdir(base_dir_.c_str(), 0700);
        }
    }

    int create_temp_file(const std::string& prefix, std::string& out_path) {
        std::lock_guard<std::mutex> lock(mtx_);

        // Always use mkstemp regardless of flag
        std::string tmpl = base_dir_ + "/" + prefix + "_XXXXXX";
        char* tmpl_buf = new char[tmpl.size() + 1];
        std::strcpy(tmpl_buf, tmpl.c_str());
        int fd = mkstemp(tmpl_buf);
        if (fd >= 0) {
            out_path = std::string(tmpl_buf);
            fchmod(fd, 0600);
        }
        delete[] tmpl_buf;
        return fd;
    }
};

class CacheService {
private:
    TempFileManager* temp_mgr_;
    FeatureFlags flags_;

    std::string compute_cache_key(const std::string& user_id, const std::string& endpoint) {
        std::hash<std::string> hasher;
        size_t h = hasher(user_id + ":" + endpoint);
        std::ostringstream oss;
        oss << std::hex << h;
        return oss.str();
    }

public:
    CacheService(FeatureFlags flags) : flags_(flags) {
        temp_mgr_ = new TempFileManager(flags_.temp_directory, true);
    }

    ~CacheService() { delete temp_mgr_; }

    bool write_cache_entry(const std::string& user_id, const std::string& endpoint,
                           const std::string& payload) {
        std::string cache_key = compute_cache_key(user_id, endpoint);
        std::string temp_path;
        int fd = temp_mgr_->create_temp_file("cache_" + cache_key, temp_path);
        if (fd < 0) return false;

        std::string data = payload;
        if (flags_.enable_cache_compression) {
            // Simplified: just prefix with marker
            data = "\x1f\x8b" + data;
        }

        ssize_t written = write(fd, data.c_str(), data.size());
        close(fd);

        if (written != (ssize_t)data.size()) {
            unlink(temp_path.c_str());
            return false;
        }

        // Atomically move to final location
        std::string final_path = flags_.temp_directory + "/cache_" + cache_key + ".dat";
        rename(temp_path.c_str(), final_path.c_str());
        return true;
    }
};

class SessionExporter {
private:
    FeatureFlags flags_;
    std::string export_dir_;

    std::string build_export_path(const std::string& session_id) {
        return export_dir_ + "/session_" + session_id;
    }

public:
    SessionExporter(FeatureFlags flags, const std::string& export_dir)
        : flags_(flags), export_dir_(export_dir) {}

    bool export_session(const std::string& session_id, const std::string& data) {
        // Validate session_id to prevent path traversal (CWE-22).
        if (!is_safe_identifier(session_id)) {
            return false;
        }

        std::string path = build_export_path(session_id);

        // Always use mkstemp for secure atomic write regardless of feature flag
        std::string tmpl = path + "_XXXXXX";
        char* buf = new char[tmpl.size() + 1];
        std::strcpy(buf, tmpl.c_str());
        int fd = mkstemp(buf);
        if (fd < 0) { delete[] buf; return false; }
        fchmod(fd, 0600);
        write(fd, data.c_str(), data.size());
        fsync(fd);
        close(fd);
        rename(buf, path.c_str());
        delete[] buf;
        return true;
    }
};

FeatureFlags load_feature_flags(const std::string& config_path) {
    FeatureFlags flags;
    flags.enable_cache_compression = false;
    flags.enable_async_logging = true;
    flags.enable_secure_temp = true;  // Default: enabled for security
    flags.cache_ttl_seconds = 300;
    flags.temp_directory = "/tmp/mobile_backend";

    std::ifstream cfg(config_path);
    std::string line;
    while (std::getline(cfg, line)) {
        if (line.find("secure_temp=true") != std::string::npos)
            flags.enable_secure_temp = true;
        if (line.find("compression=true") != std::string::npos)
            flags.enable_cache_compression = true;
        if (line.rfind("temp_dir=", 0) == 0)
            flags.temp_directory = line.substr(9);
    }
    return flags;
}

} // namespace mobile_backend

int main() {
    auto flags = mobile_backend::load_feature_flags("/etc/mobile_backend/features.conf");
    mobile_backend::CacheService cache(flags);
    mobile_backend::SessionExporter exporter(flags, flags.temp_directory + "/sessions");

    // Simulate API request handling
    cache.write_cache_entry("user123", "/api/v2/profile", "{\"name\":\"test\"}");
    exporter.export_session("abc-def-123", "{\"token\":\"secret_value\"}");

    return 0;
}
